const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs'),path=require('path'),crypto=require('crypto');
(async()=>{const browser=await chromium.launch();const page=await browser.newPage();try{await page.goto(process.argv[2],{waitUntil:'domcontentloaded'});const img=page.locator('img[alt^="Generated image"]').first();await img.waitFor({timeout:25000});const alt=await img.getAttribute('alt');const url=await img.getAttribute('src');const r=await page.request.get(url);if(!r.ok()||!r.headers()['content-type'].startsWith('image/'))throw Error('Image download failed');const data=await r.body();const target=process.argv[3];fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,data);console.log(JSON.stringify({title:await page.title(),alt,target,bytes:data.length,type:r.headers()['content-type'],sha256:crypto.createHash('sha256').update(data).digest('hex')}));}finally{await browser.close();}})();
